from pathlib import Path
import json

OUT=Path('curriculum/proposals/unit12');OUT.mkdir(parents=True,exist_ok=True)
def write(n,d): (OUT/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
tasks=[]
def task(code,mode,prompt,target,inputs=(),roles=(),support=()):
 tasks.append({'task_id':'NEW-U12-'+code,'key_id':'KEY-NEW-U12-'+code,'origin':'new_teaching_material','mode':mode,'prompt':prompt,'target_specification':target,'input_texts':list(inputs),'provisional_feature_roles':list(roles),'dependency_status':'awaiting_final_audit_ids','local_support':list(support)})

task('F01','production_morphology','Give the complete nominative, genitive, dative and accusative singular and plural of fōt. Explain the vowel alternation.','Complete newly assigned root-noun paradigm; do not infer every oblique from the nominative.',roles=['foot_paradigm'])
task('F02','production_morphology','Give the complete nominative, genitive, dative and accusative singular and plural of brycg and hęre, using the selected tables. Explain the differing stems before endings.','Complete selected feminine brycg and masculine hęre systems, including their characteristic stem behavior.',roles=['new_nominals'])
task('F03','production_morphology','Give the complete present and preterite indicative of flēon and grētan: all three persons in both numbers for each tense.','Full new strong and weak indicative systems, with the selected stem changes and endings.',roles=['new_indicatives'])
task('F04','production_morphology','For gemētan, ādrīfan, geopenian and cȳðan, give the present indicative second and third singular, the preterite second singular and the preterite third plural. Explain the stem and ending choices.','Diagnostic forms across four complete supporting systems.',roles=['new_indicatives'])
task('F05','production_morphology','Give the singular and plural commands of flēon, ādrīfan, gemētan and geopenian.','Complete selected command pairs; keep imperative and indicative morphology distinct.',roles=['new_commands'])
task('F06','production_construction','Give all six person-and-number forms of the present indicative of habban with ðæt hūs geworht, then all six preterite indicative forms with the same words. Label the finite auxiliary and the unchanged past participle.','Complete twelve-position indicative compound pattern built from actual auxiliary forms, accusative object and selected participle; this is not a new set of synthetic endings or a claim to exhaust all moods.',roles=['habban_perfect'])
task('F07','production_morphology','Give the base present and past participles of gierwan, sęttan and gewyrcean. Explain which base is used in the habban construction.','Complete two-member base systems and their explicit auxiliary use; no unassigned participial adjective endings.',roles=['participle_pairs','habban_perfect'])

task('A01','analysis','Translate and put the two narrated events in order. Identify the finite verb in each clause.','Simple preterites in ordinary successive narration.', ['Se mann cōm, and hē geseah ðæt hūs.'],['narrative_time'])
task('A02','analysis','The house was finished before the visit. Translate, preserving that order of events. Identify the morphological tense of geworhte and explain why English may use had built.','A simple Old English preterite can express an earlier past event when context supplies the relation.', ['Se mann geseah ðæt hūs ðe his sunu geworhte.'],['preterite_anterior'])
task('A03','analysis','The speaker is describing completed building work that they performed. Translate both sentences. Identify the builder, the object, the finite auxiliary and the past participle. Explain the difference between the two temporal viewpoints.','Present and past habban with a transitive past participle; active relation retained.', ['Ic hæbbe ðæt hūs geworht.','Ic hæfde ðæt hūs geworht.'],['habban_perfect'])
task('A04','analysis','In the second sentence, the speaker has just finished building the house. Translate both sentences. What work does habban do in each, and what additional information is introduced by geworht?','Lexical possession versus the completed-action construction; a familiar finite surface does not establish the same function.', ['Ic hæbbe ðæt hūs.','Ic hæbbe ðæt hūs geworht.'],['habban_perfect'])
task('A05','analysis','Translate all three sentences. Identify their subjects and the horse’s role. Which sentence names the binder? Explain the usual event/state distinction without treating it as an absolute rule.','Active and passive participant structure; contextual limits of weorðan and wesan.', ['Se mann band ðæt hors.','Ðæt hors wearð bunden.','Ðæt hors wæs bunden.'],['active_passive'])
task('A06','recognition_analysis','Translate. Identify the finite verb and the intransitive past participle. Explain why the man is not the object of an unnamed person’s action.','Wesan with intransitive past participle can express departure/anteriority; it is not mechanically passive.', ['Se mann wæs gewiten.'],['wesan_intransitive'])
task('A07','recognition_analysis','Translate, giving a simple-past rendering and a contextually possible English progressive. Identify the two verb forms and explain why the English construction is not imposed by form alone.','Bounded recognition of wesan plus present participle; no universal modern progressive tense.', ['Se mann wæs sittende.'],['wesan_present_participle'])
task('A08','analysis','Translate both reports. In each, the reported presence is simultaneous with the saying. Identify the main-clause tense and dependent mood; explain which moment the reported presence is related to.','Present and past reports with simultaneous content and contextual subjunctive.', ['Hē sægð ðæt hē sīe hēr.','Hē sægde ðæt hē wǣre hēr.'],['reported_sequence'])
task('A09','analysis','Translate. In this report the building precedes the saying. Identify the finite verbs, the participle and the object, and explain how the temporal relation is expressed.','Anterior reported content with past habban and a past participle; syncretic hæfde is analysed in its reporting context.', ['Hē sægde ðæt hē ðæt hūs geworht hæfde.'],['reported_sequence','habban_perfect'])
task('A10','analysis','Translate as a report of intention. Which action is intended, and does the sentence assert that the intended action took place?','Past willan in a report of intention; no automatic completed event or purely grammatical future.', ['Hē sægde ðæt hē wolde cuman.'],['reported_sequence','volitional_time'])
task('A11','analysis','The visit is still expected. Translate the first sentence in that setting. Translate the second as a statement of desire, and explain why English will does not always call for willan.','Contextual future reference of present indicative contrasted with lexical volition.', ['Hē cymð.','Hē wille cuman.'],['present_future','volitional_time'])

task('C01','production_translation','Translate: We have built the house. Use present habban with the selected past participle.','Productive completed-action construction with first plural auxiliary.',roles=['habban_perfect'])
task('C02','production_translation','Translate: They had built the house. The building is earlier than another past event; use preterite habban with the selected past participle.','Productive anterior construction with third plural auxiliary.',roles=['habban_perfect'])
task('C03','production_translation','Translate: The men bound the horse. Then express the horse’s binding as an agentless passive, using preterite weorðan.','Active accusative object becomes nominative passive subject; change finite number with the new subject.',roles=['active_passive'])
task('C04','production_translation','Translate: The monk says that he is here. Use the subjunctive to present his report. Then put the saying in the past, keeping his presence simultaneous with that past saying.','Reported sequence with explicit simultaneous relation, retained reference and appropriate finite forms.',roles=['reported_sequence'])
task('C05','production_translation','Translate: He said that he had built the house. Use the reporting subjunctive and preterite habban with the selected past participle.','Earlier action within a past report, without mistaking the participle for a finite verb.',roles=['reported_sequence','habban_perfect'])
task('C06','production_translation','Translate: He said that he intended to come. Use willan with the infinitive; do not assert that he actually came.','Reported intention and its temporal relation, not a mechanical would-to-past rule.',roles=['reported_sequence','volitional_time'])
task('C07','production_translation','Address one person: Prepare the food. Then translate the reply: I have prepared the food. Use gierwan in both.','New accusative-object frame and past-participle construction built on the known command and indicative auxiliary.',roles=['gierwan_object','habban_perfect'])
task('C08','production_translation','Translate: The bridge was built. Then a man came. Use an agentless passive with wesan for the completed bridge, followed by a simple preterite for the arrival.','Passive result followed by narrated event; correct feminine subject and independently inflected arrival verb.',roles=['active_passive','narrative_time'])

task('R01','reading_translation','Translate the whole new account, A house and a return. Preserve its changes between narrative, direct speech and reported intention.','Connected independent interpretation using productive records; no source-only help.',roles=['controlled_reading'])
task('R02','reading_analysis','Put these events in order: the son’s first arrival; building the house; the son’s departure; the father’s announcement; the son’s return with food. Which verb phrase places one event before the story’s first arrival?','Reconstruct connected sequence from finite tense, periphrasis and discourse.',roles=['controlled_reading','habban_perfect'])
task('R03','reading_analysis','Identify the referents of ic in the father’s speech, hē in the reported intention, and hē in the last sentence. Is the journey an intention only, or does the following narrative show a departure? Cite the relevant words.','Track reference and distinguish a reported intention from separately narrated fulfillment.',roles=['controlled_reading','reported_sequence'])
task('R04','reading_production','In Nū hæbbe ic ðæt hūs geworht, identify the subject and object. Express the house’s completed state in an agentless sentence with present wesan and the same participle.','Apply active/passive argument distinction to an understood connected context.',roles=['controlled_reading','active_passive'])

task('S01','reading_translation','Translate the complete Picts and Scots extract, using the printed local helps and original notes. Preserve the renewed attack after the Roman withdrawal.','Connected source translation without demanding recall of supplied vocabulary or constructions.',roles=['source_reading'])
task('S02','reading_analysis','Put the narrated stages in order: renewed attack; appeal to Rome; first raids; Roman withdrawal; Roman relief. Explain the cause of the renewed attack as the narrator presents it.','Reconstruct the full historical sequence and the attackers’ discovery.',roles=['source_reading','narrative_time'])
task('S03','reading_analysis','In Ðā ðæt ðā ongēaton ðā ǣrran gewinnan, identify the three occurrences of ðā and the role of the first ðæt. Use the printed source help; distinguish grammatical form from clause function.','Exact source temporal correlation, article and anticipatory object; supplied higher structure stays supported.',roles=['source_reading'])
task('S04','reading_analysis','Who sends messengers to Rome, who sends the army, and who fights the enemies? Explain how the changing subjects are recovered from context, using the original notes where indicated.','Subject reference across repeated plural pronouns; context and source apparatus, not morphology alone.',roles=['source_reading'])
task('S05','recognition_analysis','Parse wæs onweg gewiten. State which event precedes which other event, and explain why this is not an agentless passive.','Intransitive departure periphrasis and past anteriority in exact source context.',roles=['source_reading','wesan_intransitive'])
task('S06','reading_analysis','Cook’s note on Ðā onsęndon hīe him micelne hęre points out an active/passive difference from the Latin source. Identify the Old English subject, recipient and object. Give an English passive rendering that preserves their roles; no Latin or new Old English composition is required.','Voice comparison from actual participant structure, using the supplied source note.',roles=['source_reading','active_passive'])
task('S07','reading_analysis','In lǣrdon ðæt hīe fæsten worhten him tō gebeorge, what action is recommended? Is that action earlier than, simultaneous with, or prospective from the instruction? Does this clause alone state that the work was completed?','Reported instruction and relative time, with source-only instruction frame supplied.',roles=['source_reading','reported_sequence'])
task('S08','reading_analysis','Explain the comparison with rīpe ierðe in the final attack. Who are the victims, and how does the comparison contribute to the account? Use the lexical help rather than assuming a new ordinary crop meaning for the people.','Literal form, figurative comparison and contextual referent within the connected reading.',roles=['source_reading'])

examples=[
('Se mann cōm, and hē geseah ðæt hūs.','The man came, and he saw the house.','Successive narrated events.',['narrative_time']),
('Se mann geseah ðæt hūs ðe his sunu geworhte.','The man saw the house which his son had built.','Context: the house was finished before the visit. A simple preterite can represent the earlier past event.',['preterite_anterior']),
('Nū hæbbe ic ðæt hūs geworht.','Now I have built the house.','Present habban with a completed action and its result.',['habban_perfect']),
('Ðā se sunu cōm, hæfde se mann ðæt hūs geworht.','When the son came, the man had built the house.','Past viewpoint: the building is anterior to the arrival.',['habban_perfect','narrative_time']),
('Se mann band ðæt hors. Ðæt hors wearð bunden.','The man bound the horse. The horse was bound.','Active and agentless passive with the affected entity as subject.',['active_passive']),
('Ðæt hors wæs bunden.','The horse was bound.','An ordinary state/result reading, without an absolute wesan/event prohibition.',['active_passive']),
('Se mann wæs gewiten.','The man had departed.','Recognition: wesan with an intransitive past participle, not passive.',['wesan_intransitive']),
('Se mann wæs sittende.','The man sat / was sitting.','Recognition: present participle periphrasis, with interpretation supplied by context.',['wesan_present_participle']),
('Hē sægð ðæt hē sīe hēr. Hē sægde ðæt hē wǣre hēr.','He says that he is here. He said that he was here.','In both reports the presence is simultaneous with the saying.',['reported_sequence']),
('Hē sægde ðæt hē ðæt hūs geworht hæfde.','He said that he had built the house.','A completed action anterior to a past report.',['reported_sequence','habban_perfect']),
('Hē sægde ðæt hē wolde cuman.','He said that he intended to come.','Intention is reported; actual arrival is not asserted.',['reported_sequence','volitional_time']),
('Hē cymð.','He will come.','Context: the visit is still expected. Present morphology can have future reference.',['present_future'])]
text='Se mann hæfde ān hūs geworht. Ðā cōm his sunu, and se sunu geseah ðæt hūs. Se fæder cwæð: “Nū hæbbe ic ðæt hūs geworht.” Se sunu sægde ðæt hē wolde faran. Ðā se sunu gewāt, ðā sæt se fæder on ðǣm hūse. Ðā cōm se sunu, and hē sealde his fæder męte.'
